{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate absolute oral bioavailability was 11 ± 1% in volunteers after a 666-mg oral dose compared with IV infusion, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Mean absolute bioavailability of tegaserod was approximately 10% in healthy volunteers over the 2–12 mg dose range, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Absolute bioavailability of oseltamivir carboxylate was 79.0% ± 11.6% in healthy volunteers after oral oseltamivir 150 mg versus intravenous Ro 64-0802, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer absolute human evidence (acamprosate 11%, tegaserod ~10%) supports F <20%; the main contradictory high-F evidence (oseltamivir carboxylate ~80%) has lower assay-transfer and is partly conflicted by <5% records, so low is the better-supported prediction.",
  "evidence_gaps": [
    "Molecule 4 contains conflicting records for oseltamivir carboxylate/Ro 64-0802 (<5% vs ~80% absolute); inconsistent cards were discounted.",
    "Molecule 10 mixes a finasartan record (18.6%) with finasteride records (~80%); identity conflict discounted.",
    "Molecule 5 naltrexone bioavailability range 5–40% crosses the 20% threshold and is uninformative for this endpoint.",
    "Molecule 8 provides only qualitative 'low' language without a numeric threshold-relevant measurement.",
    "Molecule 2 (food matrix) and Molecule 9 (intragastric dosing) are altered conditions with lower directness."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

